        probe = path / f".probe-{os.getpid()}-{secrets.token_hex(2)}"
        probe.write_text("ok")
        ok = probe.read_text() == "ok"
        probe.unlink()
        return ok
    except Exception:
        return False


def atomic_write(path: Path, text: str) -> None:
    def _do():
